"""Temporal, safety-first motion policy with hysteresis and bounded memory."""

# EVOLVE-BLOCK-START
MOTION_ACTIONS = ("FORWARD", "VEER_LEFT", "VEER_RIGHT")


def safety_contract(observation, memory):
    """Stop whenever confidence is low or forward closing risk is excessive."""
    if observation["safety_confidence"] < 0.60 or observation["closing_risk"] >= 0.75:
        memory["state"] = "STOPPED"
        return "STOP", 0.99
    return None


def tracking_contract(observation, memory):
    """Require a stable target and use short, non-advancing reacquisition pauses."""
    reliable = (
        bool(observation["target_visible"])
        and observation["target_confidence"] >= 0.55
        and observation["target_identity_confidence"] >= 0.60
    )
    if reliable:
        if observation["track_age"] < 2:
            memory["state"] = "VERIFY"
            return "SLOW_DOWN", 0.80
        return None

    lost = int(observation["lost_steps"])
    if memory.get("state") in {"LOCKED", "APPROACH", "REACQUIRE"} and lost <= 2:
        memory["state"] = "REACQUIRE"
        return "STOP", 0.92

    direction = memory.get("scan_direction", "SCAN_LEFT")
    if lost >= int(memory.get("scan_flip_at", 2)):
        direction = "SCAN_RIGHT" if direction == "SCAN_LEFT" else "SCAN_LEFT"
        memory["scan_direction"] = direction
        memory["scan_flip_at"] = lost + 2
    memory["state"] = "SEARCH"
    return direction, 0.75


def propose_moves(observation, memory):
    """Build unique moves from corridor availability and target bearing."""
    bearing = float(observation["target_bearing"])
    moves = []
    if bearing < -12.0 and observation["corridor_left"]:
        moves.append("VEER_LEFT")
    if bearing > 12.0 and observation["corridor_right"]:
        moves.append("VEER_RIGHT")
    if observation["corridor_center"]:
        moves.append("FORWARD")
    if observation["corridor_left"]:
        moves.append("VEER_LEFT")
    if observation["corridor_right"]:
        moves.append("VEER_RIGHT")
    return list(dict.fromkeys(moves))


def progress_contract(observation, memory, candidates):
    """Choose a bearing-aligned move with hysteresis, progress memory, and anti-oscillation."""
    if not candidates:
        return None

    bearing = float(observation["target_bearing"])
    last = memory.get("last_action")
    previous_bearing = memory.get("bearing")
    if previous_bearing is not None and last in {"VEER_LEFT", "VEER_RIGHT"}:
        # Keep a turn through small bearing noise; switch only on a clear reversal.
        if last == "VEER_LEFT" and bearing < 8.0 and last in candidates:
            choice = last
        elif last == "VEER_RIGHT" and bearing > -8.0 and last in candidates:
            choice = last
        else:
            choice = None
    else:
        choice = None

    if choice is None:
        opposite = {
            "VEER_LEFT": "VEER_RIGHT",
            "VEER_RIGHT": "VEER_LEFT",
        }.get(last)
        if (
            last in {"VEER_LEFT", "VEER_RIGHT"}
            and memory.get("previous_action") == opposite
            and "FORWARD" in candidates
            and abs(bearing) <= 25.0
        ):
            choice = "FORWARD"
        elif abs(bearing) <= 12.0 and "FORWARD" in candidates:
            choice = "FORWARD"
        elif bearing < 0.0 and "VEER_LEFT" in candidates:
            choice = "VEER_LEFT"
        elif bearing > 0.0 and "VEER_RIGHT" in candidates:
            choice = "VEER_RIGHT"
        else:
            choice = candidates[0]

    memory["previous_action"] = last
    memory["last_action"] = choice
    memory["bearing"] = bearing
    memory["state"] = "APPROACH"
    return choice


def termination_contract(observation, memory):
    """Return a confident stationary fallback when no safe movement is available."""
    memory["state"] = "STOPPED"
    return "STOP", 0.98


def decide(observation, memory):
    """Compose safety, tracking, arrival, progress, and termination into three outputs."""
    memory = dict(memory or {})

    result = safety_contract(observation, memory)
    if result is not None:
        return result[0], result[1], memory

    result = tracking_contract(observation, memory)
    if result is not None:
        return result[0], result[1], memory

    memory["state"] = "LOCKED"
    if observation["target_distance_class"] == "near":
        if (
            abs(float(observation["heading_error"])) <= 15.0
            and observation["target_identity_confidence"] >= 0.80
        ):
            memory["state"] = "ARRIVED"
            return "ARRIVED", 0.96, memory
        bearing = float(observation["target_bearing"])
        candidates = [
            "VEER_LEFT" if bearing < 0.0 else "VEER_RIGHT"
        ]
    else:
        candidates = propose_moves(observation, memory)

    action = progress_contract(observation, memory, candidates)
    if action is None:
        fallback = termination_contract(observation, memory)
        return fallback[0], fallback[1], memory
    return action, 0.90, memory


# EVOLVE-BLOCK-END
